try:
    print('>>> f = delattr')
    print('>>> x = set()')
    print('>>> y = 2.3456')
    print('>>> f(x, y)')
    f = delattr
    x = set()
    y = 2.3456
    print(f(x, y))
except Exception as e:
    print(type(e), ':', e)
print()
